const principalForOwnership = `-- name: PrincipalForOwnership :one
SELECT p.kind, p.status, p.idp_groups,
  ARRAY(SELECT b.role FROM whitetower.role_bindings b
        WHERE b.principal_id = p.id AND b.revoked_at IS NULL)::text[] AS bound_roles
FROM whitetower.principals p WHERE p.id = $1
`

type PrincipalForOwnershipRow struct {
	Kind       string
	Status     string
	IdpGroups  []string
	BoundRoles []string
}

// What decides whether a principal may own an agent: its kind, its status,
// its IdP groups and its local role bindings.
func (q *Queries) PrincipalForOwnership(ctx context.Context, id uuid.UUID) (PrincipalForOwnershipRow, error) {
	row := q.db.QueryRow(ctx, principalForOwnership, id)
	var i PrincipalForOwnershipRow
	err := row.Scan(
		&i.Kind,
		&i.Status,
		&i.IdpGroups,
		&i.BoundRoles,
	)
	return i, err
}

const principalRefs = `-- name: PrincipalRefs :many
SELECT id, display_name, status FROM whitetower.principals WHERE id = ANY($1::uuid[])
`

type PrincipalRefsRow struct {
	ID          uuid.UUID
	DisplayName string
	Status      string
}

func (q *Queries) PrincipalRefs(ctx context.Context, ids []uuid.UUID) ([]PrincipalRefsRow, error) {
	rows, err := q.db.Query(ctx, principalRefs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PrincipalRefsRow
	for rows.Next() {
		var i PrincipalRefsRow
		if err := rows.Scan(&i.ID, &i.DisplayName, &i.Status); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const putGovernanceState = `-- name: PutGovernanceState :exec
INSERT INTO whitetower.governance_state (
  agent_id, lifecycle_state, lease_ttl_seconds, halt_mode, attributes, state_version, updated_at
) VALUES (
  $1, $2, $3, $4,
  $5, $6, $7
)
ON CONFLICT (agent_id) DO UPDATE SET
  lifecycle_state = EXCLUDED.lifecycle_state,
  lease_ttl_seconds = EXCLUDED.lease_ttl_seconds,
  halt_mode = EXCLUDED.halt_mode,
  attributes = EXCLUDED.attributes,
  state_version = EXCLUDED.state_version,
  updated_at = EXCLUDED.updated_at
`

type PutGovernanceStateParams struct {
	AgentID         uuid.UUID
	LifecycleState  string
	LeaseTtlSeconds int32
	HaltMode        string
	Attributes      []byte
	StateVersion    int64
	UpdatedAt       time.Time
}

// Writes what enforcement points know of the agent, at a new state version.
func (q *Queries) PutGovernanceState(ctx context.Context, arg PutGovernanceStateParams) error {
	_, err := q.db.Exec(ctx, putGovernanceState,
		arg.AgentID,
		arg.LifecycleState,
		arg.LeaseTtlSeconds,
		arg.HaltMode,
		arg.Attributes,
		arg.StateVersion,
		arg.UpdatedAt,
	)
	return err
}

